function stepPerson(dt){
    const {turn,gas,brake}=controls(dt),forward=Number(gas)-Number(brake);
    characterHeading=wrap(characterHeading+turn*(keys.sprint?2.65:2.32)*dt);
    const targetSpeed=forward*(forward<0?1.45:keys.sprint?5.55:2.23);
    footSpeed+=(targetSpeed-footSpeed)*smooth(dt,forward?7.5:11);
    if(!forward&&Math.abs(footSpeed)<.015)footSpeed=0;
    const p=pieces.char.position,nx=p.x+Math.sin(characterHeading)*footSpeed*dt,nz=p.z-Math.cos(characterHeading)*footSpeed*dt;
    const walkable=(x,z)=>clearAt(x,z,.32)&&clearOfCars(x,z,.29)
      &&city.pedestrians.every(n=>Math.hypot(n.x-x,n.z-z)>.45);
    const fromX=p.x,fromZ=p.z;
    if(walkable(nx,p.z))p.x=nx;
    if(walkable(p.x,nz))p.z=nz;
    pieces.char.rotation.y=-characterHeading;
    p.y+=(city.groundHeight(p.x,p.z)-p.y)*smooth(dt,22);
    const travelSpeed=dt>0?Math.sign(footSpeed)*Math.hypot(p.x-fromX,p.z-fromZ)/dt:0;
    person.actor.update(dt,travelSpeed);
    if(person.actor.ready)return;
    const amp=clamp(Math.abs(travelSpeed)/4,0,1);
    gait+=dt*(Math.abs(footSpeed)*2.05+.7);
    person.hips.position.y=.91+Math.abs(Math.sin(gait))*amp*.065;
    person.upper.rotation.z=Math.sin(gait)*amp*.045;
    person.upper.rotation.x=-amp*.11+Math.sin(clock*2)*.008;
    person.head.rotation.z=Math.sin(clock*1.75)*.018;
    for(const limb of person.limbs){
      const phase=Math.sin(gait)*limb.side*amp*Math.sign(footSpeed);
      limb.hip.rotation.x=phase*.82;limb.knee.rotation.x=-Math.max(0,-phase)*.79;
      limb.shoulder.rotation.x=-phase*.78;limb.elbow.rotation.x=.12+amp*.39;
    }
  }

cameraStep.text:
function cameraStep(dt){
    const driving=mode==="car",base=(driving?pieces.vehicle:pieces.char).position,heading=driving?vehicleHeading:characterHeading;
    idleOrbit=Math.max(0,idleOrbit-dt);
    if(!drag && !idleOrbit && (Math.abs(footSpeed)>1&& !driving||Math.abs(velocity)>2&&driving))orbit*=1-smooth(dt,1.45);
    const targetYaw=heading+orbit;
    cameraYaw=dt>0&&!drag?wrap(cameraYaw+wrap(targetYaw-cameraYaw)*smooth(dt,driving?14:11)):targetYaw;
    const yaw=cameraYaw,dist=driving?5.95+Math.abs(velocity)*.065:4.35;
    const lookY=base.y+(driving?1.04:1.40);
    let arm=dist;
    // Pull the camera in before a wall can obscure the player.
    for(let s=.42;s<dist;s+=.28){
      const x=base.x-Math.sin(yaw)*s,z=base.z+Math.cos(yaw)*s;
      if(!clearAt(x,z,.15)){arm=Math.max(.53,s-.29);break;}
    }
    cameraArm=dt>0&&cameraArm>0&&arm>cameraArm?cameraArm+(arm-cameraArm)*smooth(dt,8):arm;
    arm=cameraArm;
    camera.position.set(base.x-Math.sin(yaw)*arm*Math.cos(pitch),lookY+Math.sin(pitch)*arm+(driving?.48:.16),base.z+Math.cos(yaw)*arm*Math.cos(pitch));
    camera.lookAt(base.x+Math.sin(yaw)*.88,lookY+.08,base.z-Math.cos(yaw)*.88);
  }
